            local PlayerRankData = RankingListGlobalActor:GetPlayerRankData(UID, RankID, RankingCycles);
            if PlayerRankData then
                return PlayerRankData.Rank, PlayerRankData.Score;
            end
        end
    end
    return -1, 0;
end

